package ru.rutcampustrack.shared.security.admin;

import java.util.*;

/** Closed, server-owned R1 catalogue. FULL is a separate authority mode. */
public enum AdminPermission {
    DASHBOARD_VIEW("Просмотр сводки", "Сводная статистика", "overview"),
    USERS_VIEW("Просмотр пользователей", "Карточки и списки без начальных паролей", "users"),
    USERS_MANAGE("Управление пользователями", "Создание и изменение обычных пользователей", "users", USERS_VIEW),
    USER_CREDENTIALS_MANAGE("Начальные пароли и восстановление доступа", "Начальные пароли и ссылки восстановления обычных пользователей", "users", USERS_VIEW),
    USERS_ARCHIVE("Архивирование и восстановление пользователей", "Защищённое архивирование и восстановление обычных пользователей", "users", USERS_VIEW),
    GROUPS_VIEW("Просмотр групп", "Реестр и карточки групп", "groups"),
    GROUPS_MANAGE("Управление группами", "Создание, изменение, старосты, продвижение и архив групп", "groups", GROUPS_VIEW),
    SEMESTERS_VIEW("Просмотр семестров", "Список и карточки семестров", "semesters"),
    SEMESTERS_MANAGE("Управление семестрами", "Создание, изменение, активация и архив семестров", "semesters", SEMESTERS_VIEW),
    CAMPUS_MAP_MANAGE("Управление картой", "Здания, этажи и планы кампуса", "map"),
    DATA_DELETE("Окончательное удаление данных", "Дополнительно требует управление областью и защищённое подтверждение", "dangerous"),
    ADMIN_ACCESS_MANAGE("Управление администраторами и их правами", "Доступно только полному администратору", "administration");
    private final String label, description, group;
    private final List<String> requires;
    AdminPermission(String label, String description, String group, AdminPermission... requires) {
        this.label=label; this.description=description; this.group=group;
        this.requires=Arrays.stream(requires).map(Enum::name).toList();
    }
    public Entry entry() { return new Entry(name(),label,description,group,requires,this==ADMIN_ACCESS_MANAGE); }
    public record Entry(String code,String label,String description,String group,List<String> requires,boolean fullOnly) {}
    public static List<String> allCodes() { return Arrays.stream(values()).map(Enum::name).toList(); }
    public static List<String> validate(String mode,List<String> input) {
        if (input==null || !("FULL".equals(mode)||"LIMITED".equals(mode))) throw AdminAccessException.invalid();
        if ("FULL".equals(mode)) {
            if (!input.isEmpty()) throw AdminAccessException.invalid();
            return List.of();
        }
        if (input.isEmpty() || input.stream().anyMatch(Objects::isNull)) throw AdminAccessException.invalid();
        Set<String> unique=new HashSet<>(input);
        if (unique.size()!=input.size() || unique.contains(ADMIN_ACCESS_MANAGE.name())) throw AdminAccessException.invalid();
        for(String code:input) {
            AdminPermission value;
            try { value=valueOf(code); } catch(IllegalArgumentException e) { throw AdminAccessException.invalid(); }
            if(!unique.containsAll(value.requires)) throw AdminAccessException.invalid();
        }
        return allCodes().stream().filter(unique::contains).toList();
    }
}

package ru.rutcampustrack.academic.contract.enums;

public enum AssistantPermission {
    MARK_ATTENDANCE,
    MANAGE_EXCUSES,
    MANAGE_HOMEWORK,
    CANCEL_LESSONS,
    VIEW_STATS;
}

package ru.rutcampustrack.academic.assistant;

import org.springframework.stereotype.Service;
import ru.rutcampustrack.academic.contract.enums.AssistantPermission;
import ru.rutcampustrack.academic.entity.HeadmanAssistant;
import ru.rutcampustrack.academic.repository.HeadmanAssistantRepository;
import ru.rutcampustrack.academic.repository.UserRepository;
import ru.rutcampustrack.academic.repository.UserRoleGrantRepository;
import ru.rutcampustrack.shared.security.InternalJwtClaims;

import java.util.Arrays;
import java.util.Locale;
import java.util.Set;

/**
 * Fresh durable authority for assistant actions.
 *
 * <p>The actor is always taken from the validated internal JWT.  The request
 * only supplies the target group and closed permission name; neither a user
 * id nor an isHeadman flag from the caller can elevate the actor.  Repository
 * reads are intentionally uncached so revocation is visible on the next RPC.
 */
@Service
public class AssistantPermissionAuthority {

    private static final Set<String> RPC_PERMISSIONS = Set.of(
            AssistantPermission.MARK_ATTENDANCE.name(),
            AssistantPermission.MANAGE_EXCUSES.name(),
            AssistantPermission.CANCEL_LESSONS.name(),
            AssistantPermission.VIEW_STATS.name());

    private final UserRoleGrantRepository grantRepository;
    private final UserRepository userRepository;
    private final HeadmanAssistantRepository assistantRepository;

    public AssistantPermissionAuthority(UserRoleGrantRepository grantRepository,
                                        UserRepository userRepository,
                                        HeadmanAssistantRepository assistantRepository) {
        this.grantRepository = grantRepository;
        this.userRepository = userRepository;
        this.assistantRepository = assistantRepository;
    }

    public boolean allows(InternalJwtClaims claims, long targetGroupId, String rawPermission) {
        if (claims == null || claims.userId() <= 0 || targetGroupId <= 0
                || claims.groupId() == null || !claims.groupId().equals(targetGroupId)
                || claims.readOnly() || !"ACTIVE".equalsIgnoreCase(claims.status())) {
            return false;
        }
        String permission = rawPermission == null
                ? ""
                : rawPermission.trim().toUpperCase(Locale.ROOT);
        if (!RPC_PERMISSIONS.contains(permission)) {
            return false;
        }

        if ("HEADMAN".equalsIgnoreCase(claims.role())) {
            return grantRepository.findByUserIdAndRoleAndStatus(
                            claims.userId(), "headman", "active")
                    .stream()
                    .anyMatch(grant -> targetGroupId == (grant.getGroupId() == null
                            ? Long.MIN_VALUE : grant.getGroupId()));
        }
        if (!"STUDENT".equalsIgnoreCase(claims.role())) {
            return false;
        }

        return durableStudentAllows(claims.userId(), targetGroupId, permission);
    }

    /** Fresh recipient authority; permission is chosen by the server's event catalogue. */
    public boolean allowsRecipient(long userId, long targetGroupId, String permission) {
        if (userId <= 0 || targetGroupId <= 0 || !RPC_PERMISSIONS.contains(permission)
                || userRepository.findById(userId).isEmpty()) return false;
        return durableStudentAllows(userId, targetGroupId, permission);
    }

    private boolean durableStudentAllows(long userId, long targetGroupId, String permission) {
        Long studentGroupId = userRepository.findActiveStudentGrantGroupId(userId)
                .orElse(null);
        if (!Long.valueOf(targetGroupId).equals(studentGroupId)) {
            return false;
        }
        return assistantRepository.findByGroupIdAndStudentIdAndIsActiveTrue(targetGroupId, userId)
                .map(assistant -> hasPermission(assistant, permission))
                .orElse(false);
    }

    private static boolean hasPermission(HeadmanAssistant assistant, String permission) {
        String expected = permission.toLowerCase(Locale.ROOT);
        return assistant.getPermissions() != null
                && Arrays.stream(assistant.getPermissions())
                .filter(value -> value != null)
                .map(value -> value.trim().toLowerCase(Locale.ROOT))
                .anyMatch(expected::equals);
    }
}
